import heapq

def shortest(N: int, edgeList: list) -> int:
    adj = [[] for _ in range(N)]
    for u, v, w in edgeList:
        adj[u].append((v, w))

    dist = [float('inf')] * N
    dist[0] = 0
    heap = [(0, 0)]

    while heap:
        d, u = heapq.heappop(heap)
        if d > dist[u]:
            continue
        if u == N - 1:
            break
        for v, w in adj[u]:
            new_dist = d + w
            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(heap, (new_dist, v))

    return dist[N - 1] if dist[N - 1] != float('inf') else -1
